-- The schema after the TypeScript migrations 001 to 007, in one file.
--
-- Every statement is idempotent. On a database where the TypeScript service
-- applied 001 to 007, this migration changes nothing. It repeats no data
-- change of those migrations. It does not touch the TypeScript ledger table
-- `_migrations`. Do not edit this file after release: SQLx checks its hash.

-- Stop when the TypeScript ledger exists but does not hold all of 001 to 007.
-- On such a database, the old table names can still exist, and this file would
-- create empty tables next to them.
DO $$
DECLARE
  applied integer;
BEGIN
  IF to_regclass('_migrations') IS NOT NULL THEN
    EXECUTE 'SELECT count(DISTINCT version) FROM _migrations WHERE version BETWEEN 1 AND 7'
      INTO applied;
    IF applied < 7 THEN
      RAISE EXCEPTION 'the TypeScript migrations 001 to 007 are not all applied';
    END IF;
  END IF;
END
$$;

CREATE TABLE IF NOT EXISTS prices (
  id SERIAL PRIMARY KEY,
  delivery_start TIMESTAMPTZ NOT NULL,
  delivery_end TIMESTAMPTZ NOT NULL,
  price_eur_mwh DOUBLE PRECISION NOT NULL,
  area TEXT NOT NULL DEFAULT 'FI',
  fetched_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(delivery_start, area)
);

CREATE INDEX IF NOT EXISTS idx_prices_delivery_start ON prices(delivery_start);
CREATE INDEX IF NOT EXISTS idx_prices_area_delivery ON prices(area, delivery_start);

CREATE TABLE IF NOT EXISTS user_settings (
  user_id TEXT PRIMARY KEY,
  margin_cents_kwh DOUBLE PRECISION NOT NULL DEFAULT 0.49,
  transfer_day_cents_kwh DOUBLE PRECISION NOT NULL DEFAULT 2.92,
  transfer_night_cents_kwh DOUBLE PRECISION NOT NULL DEFAULT 1.37,
  tax_cents_kwh DOUBLE PRECISION NOT NULL DEFAULT 2.82752,
  vat_percent DOUBLE PRECISION NOT NULL DEFAULT 25.5,
  night_start_hour INTEGER NOT NULL DEFAULT 22,
  night_end_hour INTEGER NOT NULL DEFAULT 7,
  timezone TEXT NOT NULL DEFAULT 'Europe/Helsinki',
  area TEXT NOT NULL DEFAULT 'FI',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS api_keys (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  key_plaintext TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  last_used_at TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_api_keys_user_id ON api_keys(user_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_api_keys_single_per_user ON api_keys(user_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_api_keys_key_plaintext ON api_keys(key_plaintext);

-- The Better Auth tables keep their quoted camelCase identifiers.
CREATE TABLE IF NOT EXISTS "user" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "name" TEXT NOT NULL,
  "email" TEXT NOT NULL UNIQUE,
  "emailVerified" BOOLEAN NOT NULL,
  "image" TEXT,
  "createdAt" TIMESTAMPTZ NOT NULL,
  "updatedAt" TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS "session" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "expiresAt" TIMESTAMPTZ NOT NULL,
  "token" TEXT NOT NULL UNIQUE,
  "createdAt" TIMESTAMPTZ NOT NULL,
  "updatedAt" TIMESTAMPTZ NOT NULL,
  "ipAddress" TEXT,
  "userAgent" TEXT,
  "userId" TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "account" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "accountId" TEXT NOT NULL,
  "providerId" TEXT NOT NULL,
  "userId" TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  "accessToken" TEXT,
  "refreshToken" TEXT,
  "idToken" TEXT,
  "accessTokenExpiresAt" TIMESTAMPTZ,
  "refreshTokenExpiresAt" TIMESTAMPTZ,
  "scope" TEXT,
  "password" TEXT,
  "createdAt" TIMESTAMPTZ NOT NULL,
  "updatedAt" TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS "verification" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "identifier" TEXT NOT NULL,
  "value" TEXT NOT NULL,
  "expiresAt" TIMESTAMPTZ NOT NULL,
  "createdAt" TIMESTAMPTZ NOT NULL,
  "updatedAt" TIMESTAMPTZ NOT NULL
);

CREATE INDEX IF NOT EXISTS "account_userId_idx" ON "account" ("userId");
CREATE INDEX IF NOT EXISTS "session_userId_idx" ON "session" ("userId");
CREATE INDEX IF NOT EXISTS "verification_identifier_idx" ON "verification" ("identifier");

CREATE TABLE IF NOT EXISTS usernames (
  user_id TEXT NOT NULL PRIMARY KEY,
  username TEXT NOT NULL UNIQUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  FOREIGN KEY (user_id) REFERENCES "user" (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_usernames_username ON usernames(username);

-- Fingrid actuals (datasets 75 and 124), upsert-latest (STACK.md §5).
CREATE TABLE IF NOT EXISTS fingrid_actuals (
  dataset_id INTEGER NOT NULL,
  start_time TIMESTAMPTZ NOT NULL,
  end_time TIMESTAMPTZ NOT NULL,
  value DOUBLE PRECISION NOT NULL,
  fetched_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (dataset_id, start_time)
);

CREATE INDEX IF NOT EXISTS idx_fingrid_actuals_dataset_start
  ON fingrid_actuals (dataset_id, start_time);

-- OpenWeatherMap hourly forecasts, append-only per issuance (STACK.md §5).
CREATE TABLE IF NOT EXISTS weather_forecasts (
  point_id TEXT NOT NULL,
  issued_at TIMESTAMPTZ NOT NULL,
  target_time TIMESTAMPTZ NOT NULL,
  temp DOUBLE PRECISION NOT NULL,
  clouds DOUBLE PRECISION NOT NULL,
  uvi DOUBLE PRECISION NOT NULL,
  wind_speed DOUBLE PRECISION NOT NULL,
  wind_deg DOUBLE PRECISION NOT NULL,
  fetched_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (point_id, issued_at, target_time)
);

CREATE INDEX IF NOT EXISTS idx_weather_forecasts_point_target
  ON weather_forecasts (point_id, target_time);

-- Fingrid forecast vintages (datasets 245 and 165), append-only per issuance
-- (STACK.md §5).
CREATE TABLE IF NOT EXISTS fingrid_forecasts (
  dataset_id INTEGER NOT NULL,
  issued_at TIMESTAMPTZ NOT NULL,
  start_time TIMESTAMPTZ NOT NULL,
  end_time TIMESTAMPTZ NOT NULL,
  value DOUBLE PRECISION NOT NULL,
  fetched_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (dataset_id, issued_at, start_time)
);

-- This index serves both legs of the LATERAL latest-per-target read
-- (STACK.md §5).
CREATE INDEX IF NOT EXISTS idx_fingrid_forecasts_target_issued
  ON fingrid_forecasts (dataset_id, start_time, issued_at DESC);
CREATE INDEX IF NOT EXISTS idx_fingrid_forecasts_issued
  ON fingrid_forecasts (issued_at);

-- OpenWeatherMap daily forecasts, append-only per issuance (STACK.md §5).
-- `target_date` is the UTC calendar date of `target_dt`.
CREATE TABLE IF NOT EXISTS weather_daily_forecasts (
  point_id TEXT NOT NULL,
  issued_at TIMESTAMPTZ NOT NULL,
  target_date DATE NOT NULL,
  target_dt TIMESTAMPTZ NOT NULL,
  temp_morn DOUBLE PRECISION NOT NULL,
  temp_day DOUBLE PRECISION NOT NULL,
  temp_eve DOUBLE PRECISION NOT NULL,
  temp_night DOUBLE PRECISION NOT NULL,
  temp_min DOUBLE PRECISION NOT NULL,
  temp_max DOUBLE PRECISION NOT NULL,
  clouds DOUBLE PRECISION NOT NULL,
  uvi DOUBLE PRECISION NOT NULL,
  sunrise TIMESTAMPTZ,
  sunset TIMESTAMPTZ,
  fetched_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (point_id, issued_at, target_date)
);
